DROP TABLE IF EXISTS `md_gl_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_gl_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `item_id` bigint DEFAULT NULL,
  `item_name` varchar(128) DEFAULT NULL,
  `debit_subject_id` bigint DEFAULT NULL,
  `debit_subject_code` varchar(64) DEFAULT NULL,
  `credit_subject_id` bigint DEFAULT NULL,
  `credit_subject_code` varchar(64) DEFAULT NULL,
  `subject_name` varchar(128) DEFAULT NULL COMMENT '会计科目名称',
  `subject_code` varchar(64) DEFAULT NULL COMMENT '会计科目编码',
  `direction` varchar(10) DEFAULT NULL COMMENT '借贷方向 DEBIT/CREDIT',
  `dim_type` varchar(20) DEFAULT NULL COMMENT '维度-成本中心/项目',
  `dim_cc_type` varchar(20) DEFAULT NULL COMMENT '维度-成本中心类型(管理类/销售类/制造类)',
  `dim_travel` varchar(40) DEFAULT NULL COMMENT '维度-出差类别',
  `dim_special` varchar(2) DEFAULT NULL COMMENT '维度-是否专项项目(0/1)',
  `dim_status` varchar(20) DEFAULT NULL COMMENT '维度-表单状态(待付款/已付款)',
  `aux_rule` varchar(500) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_item` (`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3705 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='记账配置（分录生成规则）';
/*!40101 SET character_set_client = @saved_cs_client */;

